SELECT product_id, CASE WHEN quantity >= 8 THEN 'LARGE' ELSE 'SMALL' END AS quantity_tier, order_id, PERCENTILE_APPROX(unit_price, ARRAY(0.25, 0.5, 0.75)) AS unit_price_quartiles, APPROX_PERCENTILE(quantity, 0.5) AS quantity_p50, APPROX_PERCENTILE(unit_price, 0.5) AS unit_price_p50, APPROX_PERCENTILE(unit_price, 0.95) AS unit_price_p95, GROUPING(product_id) AS grouping_level FROM order_items GROUP BY GROUPING SETS ((product_id, CASE WHEN quantity >= 8 THEN 'LARGE' ELSE 'SMALL' END, order_id), (product_id, CASE WHEN quantity >= 8 THEN 'LARGE' ELSE 'SMALL' END), (product_id), ()) ORDER BY unit_price_p50 ASC;
